package com.uop.recordingtools.service;
import com.uop.recordingtools.storage.DataStore; import org.bukkit.Bukkit; import org.bukkit.ChatColor; import org.bukkit.entity.Player; import org.bukkit.scoreboard.*; import java.util.*;
public final class NameService{private final DataStore store;private final Scoreboard board=Bukkit.getScoreboardManager().getMainScoreboard();private final String TEAM="uop_hidden";public NameService(org.bukkit.plugin.java.JavaPlugin p,DataStore s){store=s;}public void hide(Player p){store.set("names.hidden."+p.getUniqueId(),true);apply(p);store.saveNow();}public void show(Player p){store.remove("names.hidden."+p.getUniqueId());remove(p);p.setCustomName(null);p.setCustomNameVisible(false);p.setDisplayName(p.getName());store.saveNow();}private void apply(Player p){if(hidden(p)){Team t=board.getTeam(TEAM);if(t==null)t=board.registerNewTeam(TEAM);t.setOption(Team.Option.NAME_TAG_VISIBILITY,Team.OptionStatus.NEVER);t.addEntry(p.getName());}String tag=tagOf(p);if(tag!=null){String n=tag+" "+p.getName();p.setCustomName(n);p.setCustomNameVisible(true);p.setDisplayName(n);}}private void remove(Player p){Team t=board.getTeam(TEAM);if(t!=null)t.removeEntry(p.getName());}public boolean hidden(Player p){return store.data().getBoolean("names.hidden."+p.getUniqueId(),false);}public void refresh(Player p){if(hidden(p))apply(p);else{remove(p);String tag=tagOf(p);if(tag!=null){p.setCustomName(tag+" "+p.getName());p.setCustomNameVisible(true);p.setDisplayName(tag+" "+p.getName());}else{p.setCustomName(null);p.setCustomNameVisible(false);p.setDisplayName(p.getName());}}}public void refreshAll(){for(Player p:Bukkit.getOnlinePlayers())refresh(p);}public void create(String id,String color,boolean bold,boolean italic,String text){text=strip(text);String val=legacy(color)+(bold?"§l":"")+(italic?"§o":"")+text;store.set("tags."+id+".text",val);store.set("tags."+id+".bold",bold);store.set("tags."+id+".italic",italic);store.saveNow();}public void edit(String id,String color,boolean bold,boolean italic,String text){create(id,color,bold,italic,text);for(Player p:Bukkit.getOnlinePlayers())if(id.equals(tagId(p)))refresh(p);}public Set<String> tags(){var s=store.data().getConfigurationSection("tags");return s==null?Set.of():s.getKeys(false);}public void deleteTag(String id){store.remove("tags."+id);for(Player p:Bukkit.getOnlinePlayers())if(id.equals(tagId(p)))removeTag(p);store.saveNow();}public void give(Player p,String id){if(!store.data().contains("tags."+id))return;store.set("names.tag."+p.getUniqueId(),id);refresh(p);store.saveNow();}public void removeTag(Player p){store.remove("names.tag."+p.getUniqueId());p.setCustomName(null);p.setCustomNameVisible(false);p.setDisplayName(p.getName());store.saveNow();}public String tagId(Player p){return store.data().getString("names.tag."+p.getUniqueId());}private String tagOf(Player p){String id=tagId(p);if(id==null||!store.data().contains("tags."+id))return null;return store.data().getString("tags."+id+".text","");}private String strip(String s){return s.length()>32?s.substring(0,32):s;}private String legacy(String c){if(c==null)return "";c=c.trim();if(c.startsWith("#")&&c.matches("#[0-9a-fA-F]{6}")){StringBuilder b=new StringBuilder("§x");for(char ch:c.substring(1).toCharArray())b.append('§').append(ch);return b.toString();}return switch(c.toLowerCase(Locale.ROOT)){case "black"->"§0";case "dark_blue"->"§1";case "dark_green"->"§2";case "dark_aqua"->"§3";case "dark_red"->"§4";case "dark_purple"->"§5";case "gold"->"§6";case "gray"->"§7";case "dark_gray"->"§8";case "blue"->"§9";case "green"->"§a";case "aqua"->"§b";case "red"->"§c";case "light_purple"->"§d";case "yellow"->"§e";case "white"->"§f";default->ChatColor.WHITE.toString();};}}
